def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    period = 9
    for r in range(h):
        c = 0
        while c < w:
            if out[r][c] != 0:
                c += 1
                continue
            a = c
            while c < w and out[r][c] == 0:
                c += 1
            b = c - 1
            if a > 0:
                v = out[r][a-1]
                for k in range(a, b+1):
                    v = v % period + 1
                    out[r][k] = v
            elif c < w:
                v = out[r][c]
                for k in range(b, a-1, -1):
                    v = (v - 2) % period + 1
                    out[r][k] = v
    return out
